def adopt_existing_programs(apps, schema_editor):
    """
    Students used to hold a free-text program (e.g. B.Tech). Make each
    distinct name (ignoring case) a real Course and tidy students to its spelling.
    """
    Course = apps.get_model('academics', 'Course')
    Student = apps.get_model('students', 'Student')
    canonical = {}
    for name in (
        Student.objects.exclude(program='')
        .order_by('id')
        .values_list('program', flat=True)
        .distinct()
    ):
        name = ' '.join(name.split())
        if name and name.lower() not in canonical:
            canonical[name.lower()] = Course.objects.create(name=name).name
    for student in Student.objects.exclude(program=''):
        wanted = canonical.get(' '.join(student.program.split()).lower())
        if wanted and wanted != student.program:
            student.program = wanted
            student.save(update_fields=['program'])


